private val Bg=Color(0xFF09090B); private val Card=Color(0xFF151518); private val Muted=Color(0xFFA3A3AD); private val Silver=Color(0xFFE5E7EB)
private val api=Retrofit.Builder().baseUrl(BuildConfig.SHADOW_API_BASE_URL).addConverterFactory(GsonConverterFactory.create()).build().create(ShadowApi::class.java)
class MainActivity:ComponentActivity(){ override fun onCreate(b:Bundle?){super.onCreate(b);setContent{ShadowApp()}} }
@Composable fun ShadowApp(){ var token by remember{mutableStateOf<String?>(null)}; if(token==null) Login{token=it}else Dashboard(token!!){token=null} }
@Composable fun Shell(content:@Composable ColumnScope.()->Unit){Surface(color=Bg,modifier=Modifier.fillMaxSize()){Column(Modifier.fillMaxSize().padding(horizontal=20.dp),content=content)}}
@Composable fun Login(onLogin:(String)->Unit){var pass by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();Shell{Spacer(Modifier.height(34.dp));Image(painterResource(com.littx.shadowbyash.R.drawable.shadow_by_ash_logo),null,Modifier.fillMaxWidth().height(250.dp),contentScale=ContentScale.Fit);Text("SHADOW SALES PANEL",color=Silver,letterSpacing=4.sp,modifier=Modifier.align(Alignment.CenterHorizontally));Spacer(Modifier.height(34.dp));Card(colors=CardDefaults.cardColors(Card),shape=RoundedCornerShape(28.dp),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(26.dp)){Text("Operator access",fontSize=30.sp,color=Silver);Text("Sign in to manage your ticket sales and customers.",color=Muted,fontSize=17.sp,modifier=Modifier.padding(top=10.dp));Text("ACCESS PASSWORD",color=Muted,letterSpacing=2.sp,modifier=Modifier.padding(top=28.dp));OutlinedTextField(pass,{pass=it},placeholder={Text("Enter your password")},singleLine=true,modifier=Modifier.fillMaxWidth().padding(top=10.dp));Button(onClick={scope.launch{runCatching{api.login(LoginReq(pass))}.onSuccess{if(it.success&&it.shadowToken!=null)onLogin(it.shadowToken)else error=it.message?:"Access denied"}.onFailure{error="Unable to connect"}}},modifier=Modifier.fillMaxWidth().padding(top=18.dp),colors=ButtonDefaults.buttonColors(Silver,Color.Black)){Text("AUTHENTICATE  →",letterSpacing=2.sp)};if(error.isNotEmpty())Text(error,color=Color(0xFFFF8A8A),modifier=Modifier.padding(top=10.dp))}};Spacer(Modifier.height(26.dp));Text("AUTHORIZED OPERATORS ONLY",color=Muted,letterSpacing=3.sp,modifier=Modifier.align(Alignment.CenterHorizontally))}}
@Composable fun Dashboard(token:String,onLogout:()->Unit){var tab by remember{mutableIntStateOf(0)};var pricing by remember{mutableStateOf(PricingRes())};var sales by remember{mutableStateOf(SalesRes())};val scope=rememberCoroutineScope();LaunchedEffect(Unit){runCatching{pricing=api.pricing(token);sales=api.sales(token)}};Scaffold(containerColor=Bg,bottomBar={NavigationBar(containerColor=Color(0xFF101012)){listOf("Overview" to Icons.Default.Dashboard,"Issue ticket" to Icons.Default.AddCard,"Sales" to Icons.Default.ReceiptLong).forEachIndexed{i,(t,ic)->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Icon(ic,t)},label={Text(t)})}}}){p->Column(Modifier.padding(p).fillMaxSize()){Row(Modifier.fillMaxWidth().padding(top=12.dp),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("SHADOW",fontSize=30.sp,color=Silver,letterSpacing=5.sp);Text("BY ASH  ·  ${if(tab==1)"NEW TICKET" else if(tab==2)"ORDER HISTORY" else "SALES DESK"}",color=Muted,letterSpacing=2.sp)};Row{IconButton({scope.launch{runCatching{sales=api.sales(token)}}}){Icon(Icons.Default.Refresh,"Refresh",tint=Silver)};IconButton(onLogout){Icon(Icons.Default.Logout,"Logout",tint=Silver)}}};when(tab){0->Overview(sales){tab=1};1->Issue(token,pricing){scope.launch{sales=api.sales(token)}};2->Sales(sales)}}}}
@Composable fun Overview(s:SalesRes,issue:()->Unit){LazyColumn(contentPadding=PaddingValues(vertical=22.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){item{Card(colors=CardDefaults.cardColors(Card),shape=RoundedCornerShape(26.dp)){Column(Modifier.padding(28.dp)){Text("YOUR SALES, AT A GLANCE",color=Muted,letterSpacing=3.sp);Text("The night starts here.",fontSize=34.sp,color=Silver,modifier=Modifier.padding(top=18.dp));Text("Track your Shadow tickets and welcome your next guest.",color=Muted,fontSize=18.sp);Button(issue,colors=ButtonDefaults.buttonColors(Silver,Color.Black),modifier=Modifier.padding(top=22.dp)){Text("＋  Issue a ticket")}}}};item{Row(horizontalArrangement=Arrangement.spacedBy(14.dp)){Stat("₹${"%,.2f".format(Locale.US,s.shadowRevenue)}","TOTAL REVENUE");Stat("${s.sales.sumOf{it.quantity}}","TICKETS SOLD")}};item{Text("RECENT SALES",color=Muted,letterSpacing=3.sp)};items(s.sales.take(5)){SaleCard(it)}}}
@Composable fun Stat(v:String,l:String){Card(colors=CardDefaults.cardColors(Card),shape=RoundedCornerShape(24.dp),modifier=Modifier.weight(1f)){Column(Modifier.padding(22.dp)){Text(l,color=Muted,letterSpacing=2.sp,fontSize=12.sp);Text(v,color=Silver,fontSize=24.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=18.dp))}}}
@Composable fun SaleCard(s:Sale){Card(colors=CardDefaults.cardColors(Card),shape=RoundedCornerShape(24.dp),modifier=Modifier.fillMaxWidth()){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(52.dp).clip(RoundedCornerShape(18.dp)).background(Color(0xFF29292F)),contentAlignment=Alignment.Center){Text(s.name.take(1).uppercase(),color=Silver,fontSize=24.sp)};Column(Modifier.padding(start=16.dp).weight(1f)){Text(s.name,color=Silver,fontSize=20.sp);Text("${s.ticketType} · ${s.quantity} ticket",color=Muted);Text("Ticket ${s.ticketId}",color=Muted,modifier=Modifier.padding(top=8.dp));if(s.shadowPaymentStatus=="free_chai_pani")Text("FREE / CHAI PANI",color=Silver,fontSize=12.sp,modifier=Modifier.padding(top=6.dp))};Text("₹${"%,.2f".format(Locale.US,s.amount)}",color=Silver,fontSize=18.sp,fontWeight=FontWeight.Bold)}}}
@Composable fun Issue(token:String,p:PricingRes,onRefresh:()->Unit){var name by remember{mutableStateOf("")};var email by remember{mutableStateOf("")};var phone by remember{mutableStateOf("")};var event by remember{mutableStateOf(p.events.firstOrNull())};var tier by remember{mutableStateOf(event?.tiers?.firstOrNull())};var qty by remember{mutableIntStateOf(1)};var free by remember{mutableStateOf(false)};var commission by remember{mutableStateOf("0%")};var custom by remember{mutableStateOf("")};var done by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();val rate=if(commission=="Custom")custom.toDoubleOrNull()?:0.0 else commission.removeSuffix("%").toDoubleOrNull()?:0.0;val total=if(free)0.0 else (tier?.price?:0.0)*qty;LazyColumn(contentPadding=PaddingValues(vertical=20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("CUSTOMER DETAILS",color=Muted,letterSpacing=3.sp,fontSize=14.sp)};item{Field("CUSTOMER NAME","Full name",name){name=it}};item{Field("EMAIL ADDRESS","guest@example.com",email){email=it}};item{Field("PHONE NUMBER · OPTIONAL","WhatsApp number",phone){phone=it}};item{Text("TICKET DETAILS",color=Muted,letterSpacing=3.sp,fontSize=14.sp,modifier=Modifier.padding(top=12.dp))};item{Drop("EVENT",event?.name?:(p.events.firstOrNull()?.name?:"Select event"),p.events.map{it.name}){v->event=p.events.find{it.name==v};tier=event?.tiers?.firstOrNull()}};item{Drop("PASS / TIER",tier?.name?:"Select pass",event?.tiers?.map{it.name}?:emptyList()){v->tier=event?.tiers?.find{it.name==v}}};item{Drop("QUANTITY",qty.toString(),(1..10).map{it.toString()}){qty=it.toInt()}};item{Text("PAYMENT STATUS",color=Muted,letterSpacing=2.sp)};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){FilterChip(selected=!free,onClick={free=false},label={Text("Paid")});FilterChip(selected=free,onClick={free=true},label={Text("Free / Chai Pani")})}};item{Text("COMMISSION",color=Muted,letterSpacing=2.sp)};item{Drop("COMMISSION",commission,listOf("0%","5%","10%","15%","20%","Custom")){commission=it}};if(commission=="Custom")item{Field("CUSTOM RATE","Percentage up to 20",custom){custom=it.filter{c->c.isDigit()||c=='.'}}};item{Text("TOTAL  ₹${"%,.2f".format(Locale.US,total)}  ·  AFTER COMMISSION  ₹${"%,.2f".format(Locale.US,total*(1-rate/100))}",color=Silver,fontSize=18.sp,modifier=Modifier.padding(vertical=8.dp))};item{Button(onClick={scope.launch{runCatching{api.ticket(token,TicketReq(name,email,phone,tier?.name?:("Ticket"),qty,event?.name?:"",if(free)"free_chai_pani" else "paid",if(free)0.0 else rate,if(free)0.0 else total*rate/100))}.onSuccess{if(it.success){done=it.ticketId?:"Ticket created";onRefresh()}}}},modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(Silver,Color.Black),enabled=name.isNotBlank()&&email.isNotBlank()){Text("CREATE & SEND TICKET  🚀")}}};done?.let{id->item{AnimatedVisibility(true,enter=fadeIn(tween(250))+scaleIn()){Card(colors=CardDefaults.cardColors(Color(0xFF26262B)),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.CheckCircle,"Success",tint=Silver,modifier=Modifier.size(64.dp));Text("TICKET CREATED",color=Silver,letterSpacing=3.sp);Text(id,color=Muted,modifier=Modifier.padding(8.dp));TextButton({done=null}){Text("Issue another ticket",color=Silver)}}}}}}}}
@Composable fun Field(label:String,placeholder:String,value:String,onChange:(String)->Unit){Column{Text(label,color=Muted,letterSpacing=2.sp,fontSize=12.sp);OutlinedTextField(value,onChange,placeholder={Text(placeholder)},singleLine=true,modifier=Modifier.fillMaxWidth())}}
@Composable fun Drop(label:String,value:String,options:List<String>,onPick:(String)->Unit){var open by remember{mutableStateOf(false)};Column{Text(label,color=Muted,letterSpacing=2.sp,fontSize=12.sp);Box{OutlinedButton({open=!open},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(value);Icon(Icons.Default.ExpandMore,"Expand")}};DropdownMenu(open,{open=false}){options.forEach{DropdownMenuItem(text={Text(it)},onClick={onPick(it);open=false})}}}}}
@Composable fun Sales(s:SalesRes){LazyColumn(contentPadding=PaddingValues(vertical=20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("ORDER HISTORY",color=Muted,letterSpacing=3.sp)};item{Text("₹${"%,.2f".format(Locale.US,s.shadowRevenue)} revenue  ·  ₹${"%,.2f".format(Locale.US,s.shadowRevenueAfterCommission)} after commission",color=Silver)};items(s.sales){SaleCard(it)}}}
